import {mansions,terms,jiazi,stems,branches} from './data.js';
export const atlases={
 yi:{label:'周易罗经',title:'掌 中 天 地',eyebrow:'THE GEOMETRY OF CHANGE',desc:'转动六十四象，展开一座古老的宇宙。',count:64,accent:'#d7bc81',legend:['甲子 · 節氣 · 周天度數','六十四卦 · 六爻成象','二十八星宿','二十四山','太極 · 八卦']},
 sky:{label:'星宿天盘',title:'仰 观 星 河',eyebrow:'THE TWENTY-EIGHT MANSIONS',desc:'四象分野，七宿相连；沿着古人的刻度认识星空。',count:28,accent:'#a8c9db',legend:['二十八宿 · 周天度数','四象 · 七宿分组','东南西北 · 四方','星点 · 装饰连线','中枢 · 星纹']},
 solar:{label:'节气时轮',title:'四 时 流 转',eyebrow:'THE WHEEL OF SEASONS',desc:'循太阳黄经，看一岁春生、夏长、秋收与冬藏。',count:24,accent:'#a8c49b',legend:['二十四节气 · 太阳黄经','春夏秋冬 · 四时','二分二至 · 四节点','十二节 · 十二中气','太阳 · 周年循环']},
 cycle:{label:'干支纪轮',title:'岁 序 相 承',eyebrow:'THE SEXAGENARY CYCLE',desc:'十干与十二支相配，六十个名字组成一轮时间。',count:60,accent:'#d4ad98',legend:['六十甲子 · 循环序号','十天干 · 十二地支','五行 · 天干对应','阴阳 · 奇偶相配','甲子 · 循环之始']}
};
export const quadrants=[{name:'青龙',dir:'东方',text:'角、亢、氐、房、心、尾、箕七宿合为东方青龙。四象是古代认识与组织星空的一种方式。'},{name:'玄武',dir:'北方',text:'斗、牛、女、虚、危、室、壁七宿合为北方玄武。名称体现传统星空分区，盘上的等分仅用于浏览。'},{name:'白虎',dir:'西方',text:'奎、娄、胃、昴、毕、觜、参七宿合为西方白虎。这里展示七宿顺序与分组，不代替实际星图。'},{name:'朱雀',dir:'南方',text:'井、鬼、柳、星、张、翼、轸七宿合为南方朱雀。可连续转动盘面，比较四象各自的七宿。'}];
const solarNotes=['冬至是北半球一年中白昼最短的节点，此后白昼逐渐增长。','小寒之名记录寒冷时节；实际天气因地区和年份而异。','大寒处于冬季末段，是二十四节气循环中的寒时标记。','立春标记传统四时中春季的开始，并不表示各地同时转暖。','雨水以降水变化命名，体现传统农时对水分的关注。','惊蛰记录春季物候意象，名称与春雷、万物生长相联系。','春分是太阳黄经零度的节点，也是传统四时的重要界标。','清明之名有天清地明之意，也是传统岁时生活的重要时节。','谷雨以雨水与作物生长命名，承接暮春的农时意象。','立夏标记传统夏季的开始，万物进入生长更旺的时段。','小满之名与作物籽粒渐满的传统农事观察相关。','芒种以有芒作物与播种农时命名，提醒人们留意时令。','夏至是北半球一年中白昼最长的节点，此后白昼逐渐缩短。','小暑标记暑热时段，节气名称体现对季节变化的观察。','大暑承接盛夏暑热的岁时意象，具体气温仍因地而异。','立秋标记传统秋季的开始，并不意味着气温立即下降。','处暑之名有暑气渐退之意，呈现夏秋之交的季节感受。','白露以露水的物候意象命名，记录清晨温度变化的感受。','秋分是太阳黄经一百八十度的节点，对应传统秋季中段。','寒露以更凉的露水时节命名，呈现深秋的岁时意象。','霜降之名关联秋末霜的物候观察，各地初霜日期并不一致。','立冬标记传统冬季的开始，是收藏与休养的岁时节点。','小雪以雪的物候意象命名，不表示各地当天必定降雪。','大雪记录仲冬的岁时意象，实际降雪由当地天气决定。'];
const element=['木','木','火','火','土','土','金','金','水','水'];
export const itemNames=id=>id==='sky'?mansions:id==='solar'?terms:id==='cycle'?jiazi:[];
export const solarLongitude=i=>(270+i*15)%360;
export function atlasItem(id,i,year=2026){
 if(id==='sky'){const q=quadrants[Math.floor(i/7)];return {name:mansions[i]+'宿',subtitle:q.dir+' · '+q.name,badge:String(i+1).padStart(2,'0')+' / 28',symbol:'✦',code:'七宿之'+['一','二','三','四','五','六','七'][i%7],metric:'四象归属',metricValue:q.name,heading:'星 空 · 分 野',text:q.text,stats:[['所属方位',q.dir],['七宿序位',String(i%7+1)+' / 7']],list:mansions.slice(Math.floor(i/7)*7,Math.floor(i/7)*7+7),note:'二十八宿按等分扇区展示；星点连线为装饰，并非实测星位。',source:'https://nadc.china-vo.org/res/r80030/',sourceName:'国家天文科学数据中心 · 四象'};}
 if(id==='solar'){const season=i>=3&&i<=8?'春':i>=9&&i<=14?'夏':i>=15&&i<=20?'秋':'冬',longitude=solarLongitude(i);return {name:terms[i],subtitle:season+'季 · '+(i%2?'节':'中气'),badge:String(i+1).padStart(2,'0')+' / 24',symbol:'☼',code:longitude+'°',metric:'太阳黄经',metricValue:'每节 15°',heading:'节 气 · 岁 时',text:solarNotes[i],stats:[['传统季节',season+'季'],['节气类别',i%2?'节':'中气']],list:terms.slice(Math.floor(i/6)*6,Math.floor(i/6)*6+6),note:'季节说明采用北半球传统岁时语境；交节时刻由历法库换算，采用北京时间。',source:'https://www.hko.gov.hk/sc/gts/time/24solarterms.htm',sourceName:'香港天文台 · 二十四节气'};}
 const stem=i%10,branch=i%12,base=1984+i,k=Math.floor((year-base)/60),years=[base+(k-1)*60,base+k*60,base+(k+1)*60];return {name:jiazi[i],subtitle:(i%2?'阴':'阳')+element[stem]+' · '+branches[branch]+'支',badge:String(i+1).padStart(2,'0')+' / 60',symbol:'◌',code:'第 '+String(i+1).padStart(2,'0')+' 位',metric:'干支相配',metricValue:stems[stem]+' + '+branches[branch],heading:'干 支 · 循 环',text:'天干每十位循环，地支每十二位循环，两者同步向前，相配六十次后回到甲子。'+jiazi[i]+'是这一轮的第'+(i+1)+'个组合。',stats:[['天干',stems[stem]+' · '+(stem+1)+'/10'],['地支',branches[branch]+' · '+(branch+1)+'/12']],list:[...stems],note:'纪年参考：'+years.join(' / ')+'。数字为农历年号常用的公历年份标记，具体日期须按换年界限判断。',source:'https://www.hko.gov.hk/sc/gts/time/stemsandbranches.htm',sourceName:'香港天文台 · 天干和地支'};
}
export function solarTermTimes(Solar,year){const table=Solar.fromYmd(year,6,15).getLunar().getJieQiTable(),out={},aliases={DONG_ZHI:'冬至',XIAO_HAN:'小寒',DA_HAN:'大寒',LI_CHUN:'立春',YU_SHUI:'雨水',JING_ZHE:'惊蛰',DA_XUE:'大雪'};for(const [name,date]of Object.entries(table)){if(date.getYear()===year)out[aliases[name]||name]=date.toYmdHms()}return out}
